function countRecursively(nowS, numPos, step){
    if(step === 0){
        var success = nowS === 0;
        return success ? 1 : 0;
    }

    var total = 0;
    for(var i = numPos + 1; i <= 9; i+=1){
        if(nowS >= i){
            total += countRecursively(nowS - i, i, step - 1);
        }
    }
    return total;
}

