function calcPrimeNumbers(){
  var max = 50023;
  var primeNumbers = new Int8Array(max + 1);

  // 除外
  primeNumbers[0] = primeNumbers[1] = 1;
  for(var i = 2, maxI = ~~Math.sqrt(max); i <= maxI; i++){
    if(primeNumbers[i]){
      continue;
    }

    for(var j = (i<<1); j <= max; j+=i){
      primeNumbers[j] = 1;
    }
  }

  var primeNums = new Int32Array(5135);
  var j = 0;
  for(var i = 1; i <= max; i++){
    if(!primeNumbers[i])
      primeNums[j++] = i;
  }

  return primeNums;
}

