function isPrime(num) {
    if (num % 3 == 0) return false;
    var limit = Math.round(Math.sqrt(num));
    var i = 1;
    while(i * 6 - 1 <= limit) {
        if (num % (i * 6 - 1) == 0 || num % (i * 6 + 1) == 0) return false;
        i++;
    }
    return true;
}

