      const worm = this.get(wormId);
      const wormIds = worm.getNextWormIds();
      if (!wormIds.length) {
        return worm;
      }
      wormIds.forEach(wormId => {
        if (this.has(wormId)) {
          return;
        }
        this.set(wormId, worm.depth + 1);
        this.queue.push(wormId);
      })
    }
