		});
		rep(m, function(){
			var a = scan() - 1;
			var b = scan() - 1;
			var c = scan();
			var d = scan();
			g[a].push([c, d, b]);
			g[b].push([c, d, a]);
		});

		var q = scan();
		rep(q, function(){
			var start = scan() - 1;
			var goal = scan() - 1;
			var type = scan();
			print(dijkstra(start, goal, type));
		});
