                if(b * (100 + x) / 100 < a[j])
                    flag = true;
                var c = Math.floor(b * (100 + y) / 100);
                if(c + 1 == b * (100 + y) / 100)
                    c++;
                sum += c;
            }
            if(flag)
                continue;
            if(max < sum){
                max = sum;
