  var sum,
      coins,
      fa = [10, 50, 100, 500],
      ck,
      amount,
      t,
      i, j;
  while (input[0] !== '0') {
    sum = +input.shift();
    coins = input.shift().split(' ').map(Number);
    amount = 0;
    for (i = 0; i < 4; i++) {
      amount += coins[i] * fa[i];
    }
    amount -= sum;
    for (i = 3; i >= 0; i--) {
      t = ~~(amount / fa[i]);
//      console.log(coins, t, amount);
      t = coins[i] < t ? coins[i] : t;
      coins[i] = coins[i] - t;
