  for (d = 1; d <= n - 1; d++) {
    for (i = 1; i <= n - d; i++) {
      m[i][i+d] = range(i, i + d).map(
        k => m[i][k] + m[k + 1][i + d] + p[i - 1] * p[k] * p[i + d]
      ).sort((a, b) => a - b)[0];
    }
  }
  console.log(m[1][n]);
})();

