class Time {
  constructor(now = 0) {
    this.now = now;
  }
  getNow() {
    return ++this.now;
  }
}
const time = new Time();

class Node {
  constructor(id) {
    this.id = id;
    this.children = [];
  }
  add(node) {
    this.children.push(node);
  }
  isVisited() {
    return !!this.start;
  }
  calc() {
    this.start = time.getNow();
    this.children.sort((a, b) => a.id > b.id);
    this.children.forEach(child => child.isVisited() || child.calc());
    this.end = time.getNow();
  }
  toString() {
    return [this.id, this.start, this.end].join(' ');
  }
}

