  var line, tlen, partition, worker, cmd, args, env, i, finished;

  line = require('fs').readFileSync(config.input, 'ascii');

  tlen = line.indexOf(config.newline);
  partition = [0];
  for (i = 1; i < workers; i++)
    partition.push(Math.floor(tlen * i / workers));
  partition.push(tlen);

