  lofst = longSegment.offset;
  sofst = shortSegment.offset;
  l = longSegment.body;
  s = shortSegment.body;
  while (slen > SEGMENT_NUMBER_LENGTH) {
    if (s[sofst] !== l[lofst]) return false;
    sofst++;
    lofst++;
    slen -= SEGMENT_NUMBER_LENGTH;
