const solver = (n, as, q, ms) => {
  const patterns = []
  for (let bit = 0; bit < (1<<n); bit++) {
    let v = 0
    for (let i = 0; i < n; i++) {
      if (bit & (1 << i)) {
        v = v + as[i]
      }
    }
    if (v !== 0) {
      patterns.push(v)
    }
  }
  const result = []
  for (let i = 0; i < q; i++) {
    if (patterns.indexOf(ms[i]) !== -1) {
      result.push("yes")
    } else {
      result.push("no")
    }
  }
  return result
}

