function lis(xs) {
  var table = [xs[0]];
  for (var i = 1; i < xs.length; i++) {
    var x = xs[i];
    table[search(table, x) + 1] = x;
    debug(table)
  }
  return table.length;
}


/**
 * Returns i s.t. table[i] < x && x <= table[i+1]
 */
function search(table, x) {
  var l = 0, h = table.length;

  if (table.length == 0 || x <= table[0]) {
    return -1;
  }

  while (l + 1 < h) {
    var pivot = Math.floor((l + h + 1) / 2);
    if (table[pivot] < x) {
      l = pivot;
    } else {
      h = pivot;
    }
    debug({l: l, h: h})
  }
  return l;
}

