function UnionFind() {
    this.parent = this;
    this.size = 1;
    this.find = function(){
        if (this.parent == this) {
            return this;
        } else {
            return this.parent.find();
        }
    };
    this.unite = function(x, y) {
        var xtop = x.find();
        var ytop = y.find();
        if (xtop == ytop) {
            return false;
        } else {
            if (xtop.size < ytop.size) {
                xtop.parent = ytop;
                ytop.size += xtop.size;
            } else {
                ytop.parent = xtop;
                xtop.size += ytop.size;
            }
            return true;
        }
    };
    this.same = function(x, y) {
        if (x.find() == y.find()) {
            return 1;
        } else {
            return 0;
        }
    };
}

