function main(){
	var heap = [];

	function heap_push(x){
		var i = heap.length;

		while(i > 0){
			var p = (i - 1) >> 1;

			if(heap[p] <= x){
				break;
			}

			heap[i] = heap[p];
			i = p;
		}
		heap[i] = x;
	}

	function heap_pop(){
		var result = heap[0];

		var x = heap.pop();

		if(!heap.length){
			return result;
		}

		var i = 0;
		while(i * 2 + 1 < heap.length){
			var a = i * 2 + 1;
			var b = i * 2 + 2;

			if(b < heap.length && heap[b] < heap[a]){
				a = b;
			}

			if(heap[a] >= x){
				break;
			}

			heap[i] = heap[a];
			i = a;
		}
		heap[i] = x;

		return result;
	}

