  function Time(sec) {
    const ONE_HOUR_PAR_SECOND   = 60 * 60;
    const ONE_MINUTE_PAR_SECOND = 60;
    return {
      getHour  :function() {
        return Math.floor(sec / (ONE_HOUR_PAR_SECOND));
