(function(stdin) {
  //declare function
  function publicBuilding(b, f, r) {
    var building = [];
    for (var i = 0; i < b; i++) {
      var floor = [];
      for (var j = 0; j < f; j++) {
        var room = [];
        for (var k = 0; k < r; k++) {
          room.push(0);
        }
        floor.push(room);
      }
      building.push(floor);
    }
    building.unshift(Array(r * 2).fill('#').join(''));
    return building;
