      var val = before[v[0] - 1][v[1] - 1];
      val.splice(v[2] - 1, 1, v[3]);
    });
    return before.map(function(v) {
      return v.map(function(w) {
        return ' ' + w.join(' ');
      }).join('\n');
    }).join('\n' + inLine + '\n');
