// a^b = a^{2^k1} * a^{2^k2} * ... *a^{2^i} * ...であることを利用して冪剰余を計算する。
// たとえばa^22 = a^16 * a^4 * a^2(22は２進数で100110) 
function modPow(a, b, n) {
    let d = 1n;
    while (b > 0) {
        if (b & 1n) {       // 最下位ビットが立っているときにa^(2^i)を掛ける。
            d = d * a % n;
        }
        a = (a * a) % n;
        b >>= 1n;
    }
    return d;
}

