            findB = i
            if (!map[i[A]]) {
                map[i].count++
                map[i][A] = true
            }
        }
    }
    if (findA === null && findB === null) {
        const area = {count: 2}
        area[A] = true
        area[B] = true
        map.push(area)
    } else if (findA !== findB) {
        const merge = {
            ...map[findA],
            ...map[findB],
            count: map[findA].count + map[findB].count - 2
        }
        map.splice(findA, 1, merge)
        map.splice(findB)
    }
}

