  var one = nextIntArray();
  var N = one[0];
  var K = one[1];
  var mod = 998244353;
  var dp = new Array(N).fill(0);
  var ruiseki = new Array(N).fill(0);
  dp[0] = 1;
  ruiseki[0] = 1;
  var list = new Array(K);
  for(var i = 0; i < K; i++){
    var tmp = nextIntArray();
    list[i] = {
      L : tmp[0],
      R : tmp[1]
    };
  }
  for(var i = 1; i < N; i++){
    for(var j = 0; j < K; j++){
      var check =  list[j];
      if(i - check.L < 0){
        continue;
      }
      if(check.L == check.R){
        dp[i] += dp[i - check.L];
      }else if(i - check.R - 1 < 0){
        dp[i] += ruiseki[i - check.L];
