                return;
            }
        }
    }

    console.log("pairwise coprime");

}

function gcd(...arg) {

    var f = (a, b) => b ? f(b, a % b) : a
    var ans = arg[0]
    for (var i = 1; i < arg.length; i++) {
        ans = f(ans, arg[i]); 
    }
    return ans;

}

