function main(){
  var k = next();
  const p = [2n,3n,5n];
  for(var j = 0; j < k; j++){
    var n = nextbig();
    var a = [nextbig(),nextbig(),nextbig()];
    var d = [0,nextbig()];
    d[2] = d[1] < a[0] ? d[1]+d[1] : d[1]+a[0];
    d[3] = d[2] < a[1] ? d[2]+d[1] : d[1]+a[1];
    var d41 = d[3] + d[1], d42 = d[2] + a[0], d43 = d[1] + a[2];
    if(d43 < d42)d42 = d43;
    if(d42 < d41)d41 = d42;
    d[4] = d41;
    var pq = new priorityQueue();
    pq.push(0n,n);
    var map = new Map();
    map.set(n,0n);
    while(1){
      var [cost,now] = pq.pop();
      if(map.has(now) && map.get(now) < cost)continue;
      if(now === 0n){
        console.log(cost.toString());
        break;
      }
      if(now < 5n){
        cost += d[now];
        if(!map.has(0n) || map.get(0n) > cost){
          map.set(0n,cost);
          pq.push(cost,0n);
        }
        continue;
      }
      for(var i = 0; i < 3; i++){
        var z = p[i], y = a[i];
        var t2 = now / z;
        var c1 = y+d[1]*(now%z);
        var c2 = (now-t2) * d[1];
        if(c2 < c1)c1 = c2;
        if(!map.has(t2) || map.get(t2) > c1+cost){
          map.set(t2,c1+cost);
          pq.push(c1+cost,t2);
        }
        if(now % z){
          t2++;
          c1 = y+d[1]*(z - now%z);
          c2 = (now-t2) * d[1];
          if(c2 < c1)c1 = c2;
          if(!map.has(t2) || map.get(t2) > c1+cost){
            map.set(t2,c1+cost);
            pq.push(c1+cost,t2);
          }
        }
      }
    }
  }
}

