function kakeruR(a, b, C, C2){
    var tmpQ, tmpR, ans;
    tmpQ = (b / C2 | 0);
    tmpR = b - (tmpQ * C2);
    ans = (a * tmpQ % C) * C2 % C + (a * tmpR);
    ans %= C;
    return ans;
}

function nCr_amari(MAX, k, MOD, C2) { //return [maxC0, maxC1, ..., maxCk]
    // 前処理
    var v_ans = [ ];
