"use strict";

function arrayOfDivisors(n){
  const divisor = new Array();
  divisor[0] = 1;

  for(let i = 2; i <= Math.sqrt(n); i++){
    if(n % i === 0){
      divisor.push(i);
    }
  }

  const p = divisor.length;

  if(Math.sqrt(n) !== divisor[p - 1]){
    divisor.push(n / divisor[p - 1]);
  }

  for(let i = p - 2; 0 <= i; i--){
    divisor.push(n / divisor[i]);
  }

  return divisor;
}

