                    CountHCut ++;
                }
            }
        }
        // console.log("hD",hDiv);
        // console.log("tRS", tmpRowSet);
        tmpSum = [0, 0, 0, 0, 0, 0, 0, 0];
        tmpSum.length = tmpRowSet.length;
        tmpCut = [];
        for (var i = 1; i <= W; i++){
            part_loop:
