    var l = String(a).length
    var ans = 0
    for (var i = 0; i < 100; i++) {
        var mask = i.toString(2)
        if (mask.length > l) {
            break
        }
        if (mask.split('1').length - 1 !== b) {
            continue
        }
        // console.log(mask)
        if (mask.length < l) {
            //最大けたではない
            ans += Math.pow(9, mask.split('1').length - 1)
        } else {
            // 最大けたのとき
