      num[i] = parseInt(num[i], 10);
      numA[i] = new Array(1000001);
      ansA[i] = new Array(1000001);
      for(var j=2; j<1000001; j++){
        ansA[i][j] = 0;
        numA[i][j] = 0;
      }
      for(var j=2; j<1000001; j++){
        numA[i][j] = 0;
        ansA[i][j] = 0;
        for(var k=0; k>=0; k){
          if(num[i]%j == 0){
            numA[i][j]++;
            num[i]/=j;
            if(str.indexOf(j) == -1){
	        	str += j+',';
            }
          }else{
            break;
          }
        }
        if(num[i] == 1){
          numB[i] = j;
          break;
        }
      }
    }
