            if(numA[k][numA2[j]]-numA[i][numA2[j]]-ansA[i][numA2[j]] > 0){
              ansA[i][numA2[j]] += numA[k][numA2[j]]-numA[i][numA2[j]]-ansA[i][numA2[j]];
            }
          }
        }
      }
    }
    var anserN = 0;
    for(var i=0; i<n; i++){
      anser[i] = 1;
      for(var j=0; j<le; j++){
        if(ansA[i][numA2[j]] > 0){
          anser[i] *= Math.pow(numA2[j], ansA[i][numA2[j]]);
        }
      }
      anserN += anser[i];
    }
    console.log(anserN%(Math.pow(10, 9)+7));
}
