function permutation(nums, k) {
    var ans = []
    if (nums.length < k) {
        return []
    }
    if (k === 1) {
        for (var i = 0; i < nums.length; i++) {
            ans[i] = [nums[i]]
        }
    } else {
        for (var i = 0; i < nums.length; i++) {
            var parts = nums.slice(0)
            parts.splice(i, 1)[0]
            var row = permutation(parts, k - 1)
            for (var j = 0; j < row.length; j++) {
                ans.push([nums[i]].concat(row[j]))
            }
        }
    }
    return ans;
}

