			if (inputS[i] === alphabets[j]){
				inputNum[i] = j;
				break;
			}
		}
	}
	var inputNPer = inputN % 25;
	var result = '';

	for(var i=0;i < inputSLength;i++){
		var temp = inputNum[i] + inputNPer
		// console.log(temp);
		if (temp > 25) temp = temp % 26;
		result += alphabets[temp];
	}
