function Main(){
	var N = nextInt();
	var list = new Array(N);
	var map = {};
	for(var i = 0; i < N; i++){
		list[i] = {
			child : []
		};
	}
	var K = 0;
	for(var i = 0; i < N - 1; i++){
		var tmp = nextIntArray();
		var Ai = tmp[0] - 1;
		var Bi = tmp[1] - 1;
		list[Ai].child.push(Bi);
		list[Bi].child.push(Ai);
		map[Ai + ":" + Bi] = {
			no : i,
			color : null
		};
	}

	var queue = [[0,0]];
	while(queue.length > 0){
		var tmp = queue.shift();
		var now = tmp[0];
		var lastColor = tmp[1];
		var child = list[now].child;
		var nowColor = 1;
		for(var i = 0; i < child.length; i++){
			var tonari = child[i];
			var left;
			var right;
			if(now > tonari){
				left = tonari;
				right = now;
			}else{
				left = now;
				right = tonari;
			}
			if(map[left + ":" + right].color == null){
				if(nowColor == lastColor){
					nowColor++;
				}
				map[left + ":" + right].color = nowColor;
				queue.push([tonari, nowColor]);
				K = Math.max(nowColor, K);
				nowColor++;

			}
		}
	}

	myout(K);
	var output = new Array(N - 1);
	var mae = new Array(N - 1);
	var keys = Object.keys(map);
	for(var i = 0; i < keys.length; i++){
		mae[i] = map[keys[i]];
	}
	mae.sort(function(a,b){
		return a.no - b.no;
	});
	for(var i = 0; i < N - 1; i++){
		output[i] = mae[i].color;
	}
	myout(myconv(output,9));
}

