function countDivisor(m,d){
  function cntDiv(n){
    if(n*n > m)return 0;
    if(m%n === 0 && m/n < 10) return cntDiv(n+1) + (m/n*10+n < d && m/n!==n)?2:1;
    else return cntDiv(n+1);
  }
  if(m<4) return 0;
  else return cntDiv(2) + countDivisor(m-1,d);
}

