    	var j = sortedArray.length - 1;
    	sumRight = sortedArray[j];
    	for (var i=0;i < j;i++) {
    		sumLeft += i;
    		if (sumLeft <= sumRight) {
    			continue
    		} else {
    			j--;
    			while (sumRight < sumLeft && j > i) {
    				sumRight += sortedArray[j];
    				j--;
    			}
    		}
    	}
    	return Math.min(sumLeft, sumRight)
    }
