const Main = (arg) => {
  let input = arg.trim().split('\n');
  let n = input[0].split(' ').map(Number)[0];
  let k = input[0].split(' ').map(Number)[1];
  // k: blue    n - k: red
  // console.log({ n, k });
  let mod = 1e9 + 7;

  // 組み合わせ aCb
