    for (let i = a; i > a - b; i--) {
      numerator *= i;
    }
    for (let j = b; j > 0; j--) {
      denominator *= j;
    }
    let number = numerator / denominator;
    return number;
  }

  for (let i = 1; i <= k; i++) {
    let answer = combination(n - k + 1, i) * combination(k - 1, i - 1);
    answer = Math.round(answer % mod);
    answer = (answer === -0) ? 0 : answer;
    console.log(answer);
  }

}
