function Main(input) {
  var A = parseInt(input[0], 10);
  var B = parseInt(input[1], 10);
  var C = parseInt(input[2], 10);
  var D = parseInt(input[3], 10);

  var cNum = A % C !== 0 ? Math.floor(A / C) + 1 : Math.floor(A / C);
  var dNum = A % D !== 0 ? Math.floor(A / D) + 1 : Math.floor(A / D);

  var baisuu = [];

  // A~Bの範囲のCの倍数を求める
  while (C * cNum <= B) {
    baisuu.push(C * cNum);
    cNum++;
  }
  // A~Bの範囲のCの倍数を求める
  while (D * dNum <= B) {
    baisuu.push(D * dNum);
    dNum++;
  }

