    maxValue = (W * H) / 2;
    maxCount = 1;
  }
  else {
    var minSquireX = y/x * H;
    var minSquireY = x/y * W;
    var minSquire = 0;

    if(minSquireX < W){
      minSquire = (x - minSquireX) * (H -y);
