var _fibs = [0, 1];
function fib(n) {
  for(var i = _fibs.length; i <= n; i++){
    _fibs[i] = (_fibs[i-1] + _fibs[i-2])%divider;
  }
}

function fibs(n) {
  if(n<=0){return 1;}
  fib(n);
  return _fibs.slice(n, n + 1)[0];
}

