        }
      }else{
        if(S[i][j]=="."){
          dp1[i][j]=dp1[i][j-1]+1;
        }else{
          dp1[i][j]=0;
        }
      }
    }
  }
  for(var i=0;i<H;i++){
    for(var j=W-2;j>=0;j--){
      if(S[i][j]=="."){
        if(dp1[i][j+1]!=0){
