          dp2[i][j]=dp2[i-1][j]+1;
        }else{
          dp2[i][j]=0;
        }
      }
    }
  }
  for(var i=H-2;i>=0;i--){
    for(var j=0;j<W;j++){
      if(S[i][j]=="."){
        if(dp2[i+1][j]!=0){
          dp2[i][j]=dp2[i+1][j];
