    var sides = args.slice(1, args.length - 1).map(l => {
        var value = l.split(" ").map((v) => parseInt(v, 10));
        return value.sort((a, b) => a - b)
    });
    var values = args[args.length - 1].split(" ").map(v => parseInt(v, 10));
    values.sort((a, b) => b - a);
    values = values.splice(0, num);

