      var min_a = array_a[0];

      for ( var j=0;j<array_a.length;j++){
        var tmpdist = (array_a[j] - ave_a) * (array_a[j] - ave_a);

        if ( tmpdist < mindist ){
          min_a = array_a[j];
        } else if (tmpdist == mindist ){
          min_a = array_a[j] < min_a ? array_a[j] : min_a;
        }

