      var value = 0;
      for ( var j=0;j<array_a.length;j++){
        if ( array_a[j] <= min_a){
          value += array_a[j] - min_a;
        } else {
          value += ( -array_a[j] + min_a);
        }
      }

      console.log('%d %d', min_a, value);


    }
  }

