function QuickSelect(a,k){
  --k;
  var l=0,r=a.length-1;
  while(l<r){
    var i=l-1,j=r,m=l+r>>1;
    var p=a[m],t;a[m]=a[r];
    while(1){
      while(i<j)if(p<a[++i])break;
      while(i<j)if(a[--j]<p)break;
      if(j<=i)break;
      t=a[i];a[i]=a[j];a[j]=t;
    }
    a[r]=a[i];a[i]=p;
    if(i<k)l=i+1;else if(k<i)r=i-1;else break;
  }
  return a[k];
}

