    if (x < S[0]) {
      cache[k][x] = (x * fac[k]) % 1000000007;
    } else {
      let sum = 0;

      let i = 0;
      while (S[i] <= x && i < N) {
        sum += calc(k-1, x % S[i]);
        i += 1;
      }

      cache[k][x] = (sum * Perm(i, k)) % 1000000007;
