      next3[1]+next3[0]+next3[2] != 'AGC' &&

      next4[0]+next4[1]+next4[3] != 'AGC' &&
      next4[0]+next4[2]+next4[3] != 'AGC'
    ){
      ans += calc(N, next.slice(-4), cnt+1);
      ans %= 1000000007;
    }
  }
  map[key] = ans;
  return ans;
}

