    }
    // 文字列の最後C[N-1]は無条件にインクリメントする
    number[C[N - 1]]++;

    // 同じ数字を無作為に2つ取得する(Combination)
    Object.keys(number).forEach(function (keys) {
        result += Co(number[keys], 2);
        result %= MOD;
    });

    // 初期状態もカウントしていいので +1
