const SPAC = " ";
const NOSP = "";

function Main(input){
	input = input.split(BKRT).map(a=>a.split(SPAC));
  const strShift = ()=>{
  	var a = input.shift();
    	var b = a.shift();
    	if(a.length)input.unshift(a);
      return b;
  }
  const intShift = ()=>~~strShift();

  var N = intShift();
  var M = intShift();
  var o = [];
  for(var i = 0; i < N ; i++){
  	o.push([intShift(),intShift()]);
  }
  o.sort((a,b)=>a[0]-b[0]);

  var ans = 0;
  while(M){
  	var b = o.shift();
    if(M >= b[1]){
    	M -= b[1];
      ans += b[0] * b[1];
    }else{
    	ans += b[0] * M;
    	M = 0;
    }
  }

  return ans;
}

