}

function binarySearchSort(arr){
  var n=arr.length;
  var newArr=[];
  for(let i=0;i<n;i++){
    var d=0,m=0,u=n-1;
    m=Math.floor((d+u)/2);
    while(!(d>u)){
      if(newArr[m]<arr[i]){
        d=m+1;
      }else{
        u=m-1;
      }
      m=Math.floor((d+u)/2);
    }
    newArr.splice(m+1,0,arr[i]);
  }
  return newArr;
}


