        if (n % 2 === 0) return [2, ...getPrimeFactors(n / 2)];
        if (n % 3 === 0) return [3, ...getPrimeFactors(n / 3)];
        if (n % 5 === 0) return [5, ...getPrimeFactors(n / 5)];
        const limit = Math.sqrt(n);
        while (prime <= limit) {
            if (n % prime === 0) return [prime, ...getPrimeFactors(n / prime)];
            prime += step;
            step = 6 - step;
        }
        return [n];
    };

