function Main(input) {
  input = input.split("\n");
  var N = parseInt(input[0]);
  A = new Array(N);
  tmp=input[1].split(" ");
  for(i=0;i<N;i++){
    A[i]=parseInt(tmp[i]);
  }
  var ans = 1;
  var flag=0;
  var ans=0;
  //var c=0;
  var c=1;
  B = new Array(A[0]).fill(1);
  for(i=1;i<N;i++){
    if(flag==2){
      for(j=0;j<B.length;j++){
        //c=Math.max(c,B[j]);
        if(B[j]!=B[0]){
          flag=1;
          break;
        }else{
          flag=0;
        }
      }
    }
    if(A[i]>A[i-1]){
      for(j=0;j<A[i]-A[i-1];j++){
        B.push(1);
        if(flag!=0){
          flag=1;
        }
      }

    }else if(flag==0){
      B[A[i]-1]=B[A[i]-1]+1;
      B=B.slice(0,A[i]);
      if(B.length!=1){
        flag=1;
        c++;
      }
    }else if(flag==1){
      B=B.slice(0,A[i]);
      for(j=A[i]-1;j>=0;j--){
        if(B[j]==c){
          B[j]=1;
        }else if(B[j]!=c){
          B[j]=B[j]+1;
          flag=2;
          break;
        }
      }
    }
  }
  for(i=0;i<B.length;i++){
    ans=Math.max(ans,B[i]);
  }
  console.log('%s', ans);
}

