function f(i, x, n, acc) {
  if (x > n) return acc;
  var p = new Array(10);
  var m = x;
  while (m > 0) {
    switch(m % 10) {
      case 3: {
        p[3] = true;
        break;
      }
      case 5: {
        p[5] = true;
        break;
      }
      case 7: {
        p[7] = true;
        break;
      }
      default: {
        break;
      }
    }
    m = Math.floor(m / 10);
  }
  acc += p[3] === true && p[5] === true && p[7] === true ? 1 : 0;
  acc += f(i + 1, Math.pow(10, i) * 3 + x, n, 0);
  acc += f(i + 1, Math.pow(10, i) * 5 + x, n, 0);
  acc += f(i + 1, Math.pow(10, i) * 7 + x, n, 0);
  return acc;
}

