    ans = BigInt(1);
    let _x = BigInt(x)
    while(n != 0){
        if(n & 1) ans = ans*_x % BigInt(MOD);
        _x = _x*_x % BigInt(MOD);
        n = n >> 1;
    }
    return Number(ans);
}

