                for (let bc = minBC; bc <= N; bc += K) {
                    numBC++;
                }
                numBCCache1[minBC] = numBC;
            }
            count += numBC * numBC;
        } else {
            // bc が任意の組で満たさない
            let numBC = numBCCache2[minBC];
