function Main(input){
  input=input.trim().split(/\s+/).map(x=>x-0);
  var N=input.shift();
  var C=input.shift();
//時計回りだろうが反時計回りだろうが寿司の番号は反時計回りにつける。
  var X=[input[0]];//移動距離
  var V=[input[1]];//カロリー合計
  for(let i=1;i<N;i++){
