	var INPUT_MODE_WORD = 1;
	var input_mode = INPUT_MODE_WORD;

	/**
	 * @param {string} line 
	 * @param {string} [end] 
	 */
	function write (line, end) {
		ostream.cork();
		ostream.write(line + (undefined === end ? os.EOL : end));
		ostream.uncork();
	}
