      visit[y][x + 1] = true;
       queue.push([y, x + 1, count + 1]);
    }
  }
  //goal + 1以外の点はすべて変換化
  if(goal == 10000000){
     myout(-1);
  }else{
     var dot = 0;
     for(var i = 0; i < H; i++){
       for(var j = 0; j < W; j++){
         if(list[i][j] == "."){
            dot++;
         }
       }
     }
     dot -= (goal + 1);
    myout(dot);
  }
}

