                res = (menbers[fn[1]] - menbers[fn[0]]) === fn[2];
            } else if (menbers[fn[0]] !== undefined) {
                menbers[fn[1]] = menbers[fn[0]] + fn[2];
            } else if (menbers[fn[1]] !== undefined) {
                menbers[fn[0]] = menbers[fn[1]] - fn[2];
