    H -= cnt * strongest;

    if(H <= 0) {
        console.log(cnt);
        return;
    } 

    AB.sort((a,b)=>b[1] - a[1]);

    for(let i=0; i<N; i++) {
        H -= AB[i][1];
        cnt++;

        if(H <= 0) break;
