    // 平方根を保存
    var s = Math.floor(Math.sqrt(n));

    var r = 0;

    var result = {};

    // 2から平方根までの素因数を求める
    for (var i = 2; i <= s; i++) {

        if ((n % i) == 0) {

            r = 0; // 指数カウンタクリア

            do {

                r++; // 指数カウンタプラス

                n = n / i;

            } while ((n % i) == 0);

            // 素因数iを指数とともに保存
            result[i] = r;

        }

    }

    // 残った素数を追加
    if (n > s) {
        result[n] = 1;
    }

    return result;

}

