"use strict";


const binarySearch = (array, target) => {
    let high = array.length - 1;
    let low  = 0;

    while(low < high) {
        let mid = Math.floor((low + high) / 2); 

        if(target === array[mid]) {
            return mid;
        }

        if(target < array[mid]) {
            high = mid - 1;
        } else {
            low  = mid + 1;
        }
    }

    if(array[low] < target)
        return low + 1;
    if(array[low] >= target)
        return low;
    return 0;
}

