            if (T[j] !== str_S[j] && str_S[j] !== "?") { break; }
            if ((T[j] === str_S[j] || str_S[j] === "?") && j === T.length - 1) { ans = i - T.length + 1; }
        }

        if (ans !== -1) { break; }
    }

    if (ans === -1) { console.log("UNRESTORABLE") }
    else {
        for (var i = 0; i < S_.length; i++) {

            if (S_[i] === "?" && i !== ans) { S_[i] = "a" }
            if (i === ans) {
                for (var j = 0; j < T.length; j++) {
                    S_[i + j] = T[j];
                }
                i += T.length;
            }
        }

        console.log(S_.join(""));
    }
});

