    if (i >= a.length) {
        return 0;
    }
    var ans1 = 1;
    for (var j = i + 1; j < a.length; j++) {
        ans1 *= 3;
    }
    var ans2 = dfs(i + 1, a);
    var ans = 0;
    if (a[i] % 2 == 0) {
        ans = ans1 + 2 * ans2;
    }
    else {
        ans = 2 * ans1 + ans2;
    }
    return ans;
}

