    const lines = input_string.split('\n');
    const nm = space_input(lines[0])
    const N = nm[0]
    const M = nm[1]
    let ab = lines.splice(1).map(l=>space_input(l))
    let pts = new Array(N+1)
    for(let i=0;i<N+1;++i){
        pts[i]=[]
    }
    for(let e of ab){
        e[0]--
        e[1]--
        pts[e[0]].push(e[1])
        pts[e[1]].push(e[0])

