function Main(input) {

    var n = parseInt(input[0], 10);
    var dstr = input[1].split(' ');
    var d = new Array(n);
    for (var i = 0; i < n; i++) {
        d[i] = parseInt(dstr[i], 10);
    }
    var m = parseInt(input[2], 10);
    var tstr = input[3].split(' ');
