        if (a < b) {
            return -1;
        }
        if (a > b) {
            return 1;
        }
        return 0;
    });

    t.sort(function(a, b) {
        if (a < b) {
            return -1;
        }
        if (a > b) {
            return 1;
        }
        return 0;
    });

    for (var i = 0, j = 0; i < m; i++) {
        var found = false;
        for (; j < n; j++) {
            if (t[i] == d[j]) {
                found = true;
                j++;
                break;
            }
        }
        if (!found) {
            break;
        }
    }

