        return Math.round(fact(total)/(fact(a)*fact(total-a)));
    }

    var evenCombi = Math.pow(2,even);

    var oddCombi = 0
    if(amari===0){
        for(var i = 0;i<=odd;i+=2){
            oddCombi += combi(odd,i);
        }
    } else {
        for(var i = 1;i<=odd;i+=2){
            oddCombi += combi(odd,i);
            console.log(combi(odd,i));
        }
    }

    console.log(evenCombi*oddCombi);

}
