  var s = s.split("\n");
  var n = parseInt(s[0], 10);
  var a = s[1].split(" ").map(e => parseInt(e, 10));
  var acc = 0, cnt = 0, arr = [];
  for (var i = 0; i < n; i++) {
    acc += a[i];
    if (i === 0) {
      if (acc === 0) {
        if (a[i + 1] >= 0) {
          acc -= (a[i + 1] - 1);
          if (acc === 0) acc--;
          cnt += Math.abs(acc);
        } else {
          acc += (Math.abs(a[i + 1]) - 1);
          if (acc === 0) acc++;
          cnt += acc;
        }
      }
