      if (arr[i - 1] > 0) {
        if (acc >= 0) {
          cnt += (acc + 1);
          acc -= (acc + 1);
        }
      } else {
        if (acc <= 0) {
          cnt += (Math.abs(acc) + 1);
          acc += (Math.abs(acc) + 1);
        }
      }
    }
    arr.push(acc);
  }
  console.log(cnt);
}

