"use strict";

const main = arg => {
    arg = arg.trim().split("\n");
    const N = parseInt(arg[0].split(" ")[0]);
    const M = parseInt(arg[0].split(" ")[1]);

    const ab = arg.slice(1, N + 1).map(n=>n.split(" ").map(l=>parseInt(l)));

    // グラフ用の2次元配列を作る
    const mx = [...Array(N)].map(n=>[...Array(N)].fill(0));

    for(let i in ab) {
        const from = ab[i][0] - 1;
        const to   = ab[i][1] - 1;

        mx[from][to] = 1;
        mx[to][from] = 1;
    }

    let sum = 0;

    const dfs = (v, visited) => {
        if (visited.every(v=>v===true)) sum++;

        for (let i = 0; i < N; i++) {
          if (mx[v][i] === 0) continue;
          if (visited[i]) continue;

          visited[i] = true;
          dfs(i, visited);
          visited[i] = false;
        }

        return;
    }

    const visited = [true, ...[...Array(N - 1)].map(n=>false)];
    dfs(0, visited);

    console.log(sum);
}
