        min = node[H][x][1]
        revise[0] = node[H][x][0];
        revise[1] = node[H][x+1][0];
      }
    };
    for(y = 0;y < H;y++){
      if(node[y][W][2] < min && node[y][W][0] != node[y+1][W][0]){
        min = node[y][W][2]
        revise[0] = node[y][W][0];
        revise[1] = node[y+1][W][0];
      }
    };

    for(y = 0;y < H+1;y++){
      for(x = 0;x < W+1;x++){
        if(node[y][x][0] == revise[1]){
          node[y][x][0] = revise[0];
        }
      }
