function Inverse(arr){
  var N=arr.length;
  var M=Math.pow(2,N);
  var returnArray=[];
  for(var k=0;k<2501;k++){
    returnArray[k]=0;
  }
  for(var i=0;i<M;i++){
    var b=zeroPadding((i.toString(2)),N);
    var index=0;
    for(var j=0;j<N;j++){
      index += (b[j]==='1')?arr[j]:0;
    }
    returnArray[index]++;
  }
  return returnArray;
}

